insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','risk',$psych$Ideação e comportamento suicida$psych$,$psych${"priority":"alta","summary":"Pensamentos de morte, ideação, plano ou tentativa. É o sinal prioritário de segurança: sempre investigar de forma direta e acolhedora, e registrar.","draft":"Investigar presença de ideação suicida (pensamentos de morte, desejo de morrer), existência de plano e método, tentativas prévias e fatores de proteção. Registrar gravidade e rede de apoio.","screening":["Nos últimos tempos, você chegou a pensar que não valeria a pena viver, ou em se machucar?","Esses pensamentos chegaram a virar um plano? Você pensou em como faria?","Já tentou tirar a própria vida alguma vez? Quando?","O que te segura hoje — o que te faz continuar? (fatores de proteção)"],"observe":["Desesperança, sensação de ser um peso para os outros, despedidas, doação de pertences","Acesso a meios (medicação acumulada, arma de fogo)","Tentativa prévia, histórico familiar de suicídio, perda recente"],"reminder":"Se presente: avaliar gravidade e iminência, construir plano de segurança, acionar rede de apoio e encaminhar conforme o protocolo da clínica. O sistema lembra — a decisão clínica é sua."}$psych$::jsonb,0,0,array[$psych$DSM-5-TR$psych$,$psych$CID-11$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','risk',$psych$Autolesão não suicida$psych$,$psych${"priority":"alta","summary":"Comportamento de se machucar de propósito, sem intenção de morrer (cortes, queimaduras, escoriações). Frequentemente ligado a alívio de tensão emocional.","draft":"Investigar autolesão sem intenção suicida: forma, frequência, gatilhos e função (o que sente antes e depois). Diferenciar de ideação suicida.","screening":["Você tem se machucado de propósito, sem a intenção de morrer (por exemplo, cortes ou queimaduras)?","Com que frequência isso acontece? O que costuma vir antes?","O que você sente antes e o que sente depois?"],"observe":["Cicatrizes, roupas cobrindo braços/pernas mesmo no calor","Relato de alívio de tensão ou de 'sentir algo' após o ato"],"reminder":"Avaliar a função do comportamento e o risco associado; distinguir de intenção suicida; encaminhar conforme o protocolo da clínica."}$psych$::jsonb,0,0,array[$psych$DSM-5-TR$psych$,$psych$ABA/TEA$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','risk',$psych$Risco a terceiros / heteroagressividade$psych$,$psych${"priority":"alta","summary":"Pensamentos, impulsos ou histórico de agredir outra pessoa. Exige atenção a alvo específico e acesso a meios.","draft":"Investigar impulsos ou pensamentos de agredir terceiros, existência de alvo específico, acesso a meios e histórico de violência.","screening":["Tem tido pensamentos ou impulsos de machucar outra pessoa?","Existe alguém específico? Você teria como (acesso a meios)?","Já se envolveu em situações de agressão antes?"],"observe":["Irritabilidade intensa, ideias persecutórias, histórico de violência","Menção a alvo concreto e a um plano"],"reminder":"Considerar dever de proteção/aviso conforme a legislação e o Conselho, e o protocolo da clínica. O sistema lembra — a conduta é sua."}$psych$::jsonb,0,0,array[$psych$DSM-5-TR$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','risk',$psych$Violência, abuso ou negligência$psych$,$psych${"priority":"alta","summary":"Exposição a violência (física, psicológica, sexual) ou negligência, sofrida pela pessoa ou por alguém sob seus cuidados.","draft":"Investigar exposição a violência ou negligência, atual ou passada, incluindo risco a crianças, adolescentes, idosos ou pessoas vulneráveis do convívio.","screening":["Você está passando, ou já passou, por alguma situação de violência ou negligência?","Há crianças, adolescentes ou idosos em situação de risco no seu convívio?","Você se sente seguro(a) em casa e nas suas relações?"],"observe":["Relatos indiretos, medo ao falar de certas pessoas, sinais físicos inexplicados","Isolamento imposto, controle financeiro ou de circulação"],"reminder":"Atentar para notificação compulsória quando envolver criança, adolescente ou idoso; acionar rede de proteção conforme o protocolo da clínica."}$psych$::jsonb,0,0,array[$psych$CID-11$psych$,$psych$Manual Neuropsicologia (CFP)$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','risk',$psych$Sinais de crise aguda$psych$,$psych${"priority":"alta","summary":"Desorganização importante, agitação intensa, sintomas psicóticos agudos ou dissociação marcada que exigem cuidado imediato.","draft":"Registrar sinais de crise aguda (desorganização, agitação, alteração do juízo de realidade, dissociação) e avaliar necessidade de cuidado imediato.","screening":["Você tem se sentido fora de controle, muito agitado(a) ou desconectado(a) da realidade?","Tem ouvido ou visto coisas que outras pessoas não percebem?"],"observe":["Discurso desorganizado, agitação psicomotora, alteração do juízo de realidade","Episódios de dissociação ('desligar', não lembrar de trechos)"],"reminder":"Avaliar necessidade de encaminhamento imediato/emergência e suporte psiquiátrico, conforme o protocolo da clínica."}$psych$::jsonb,0,0,array[$psych$DSM-5-TR$psych$,$psych$CID-11$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Funcionamento cognitivo$psych$,$psych${"framework":"Neuropsicologia","summary":"Como estão atenção, memória, linguagem, funções executivas e orientação — o 'como a mente está operando'.","draft":"Organizar observações sobre atenção, memória, linguagem, funções executivas e orientação.","explore":["Atenção e concentração no dia a dia (foco, distração, esquecimentos)","Memória para fatos recentes e antigos","Linguagem e comunicação (encontrar palavras, compreender, se expressar)","Organização, planejamento e tomada de decisão"]}$psych$::jsonb,0,0,array[$psych$Manual Neuropsicologia (CFP)$psych$,$psych$DSM-5-TR$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Funcionamento afetivo e emocional$psych$,$psych${"framework":"Clínico","summary":"Estado de humor, afeto predominante e capacidade de regular emoções.","draft":"Organizar observações sobre humor predominante, oscilações, afeto e regulação emocional.","explore":["Humor predominante nas últimas semanas","Oscilações, irritabilidade, apatia ou anedonia","Como lida com emoções intensas (raiva, medo, tristeza)"]}$psych$::jsonb,0,0,array[$psych$DSM-5-TR$psych$,$psych$CID-11$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Funcionamento adaptativo e cotidiano$psych$,$psych${"framework":"Funcional","summary":"Como a pessoa se vira no dia a dia: autocuidado, trabalho/estudo, relações e autonomia.","draft":"Organizar observações sobre autocuidado, desempenho no trabalho/estudo, relações e autonomia.","explore":["Autocuidado e rotina básica (higiene, alimentação, sono)","Desempenho e faltas no trabalho ou nos estudos","Relações interpessoais e vida social","Autonomia para tarefas do dia a dia"]}$psych$::jsonb,0,0,array[$psych$ABA/TEA$psych$,$psych$Manual Neuropsicologia (CFP)$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Desenvolvimento e história de vida$psych$,$psych${"framework":"Desenvolvimental","summary":"Trajetória: marcos do desenvolvimento, infância, adolescência e eventos significativos.","draft":"Organizar a linha de vida: marcos do desenvolvimento e eventos significativos (perdas, mudanças, adoecimentos).","explore":["Gestação, parto e marcos do desenvolvimento (quando pertinente)","Infância e adolescência: como foram","Eventos marcantes (perdas, mudanças, separações, adoecimentos)"]}$psych$::jsonb,0,0,array[$psych$ABA/TEA$psych$,$psych$Manual Neuropsicologia (CFP)$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Contexto familiar e social$psych$,$psych${"framework":"Sistêmico","summary":"Configuração familiar, rede de apoio, trabalho/escola e contexto cultural.","draft":"Organizar observações sobre configuração familiar, rede de apoio e contexto social/cultural.","explore":["Com quem mora e como é a dinâmica familiar","Rede de apoio: com quem pode contar","Trabalho/escola e contexto socioeconômico e cultural"]}$psych$::jsonb,0,0,array[$psych$CID-11$psych$,$psych$ABA/TEA$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Avaliação funcional do comportamento$psych$,$psych${"framework":"Análise do comportamento aplicada","summary":"Leitura de antecedentes, comportamento e consequências (ABC) para entender a função do que acontece.","draft":"Organizar a análise funcional: o que vem antes (antecedentes), o comportamento em si e o que vem depois (consequências).","explore":["Em que situações o comportamento/queixa aparece e em quais não aparece","O que costuma vir antes (gatilhos) e depois (consequências)","Que função o comportamento parece cumprir para a pessoa"]}$psych$::jsonb,0,0,array[$psych$ABA/TEA$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Hipóteses de trabalho e formulação$psych$,$psych${"framework":"Descritivo","summary":"Organização PROVISÓRIA do caso para guiar a escuta — descritiva, sem diagnóstico automático.","draft":"Registrar hipóteses de trabalho provisórias que orientam a escuta, sempre revisáveis e sem valor diagnóstico automático.","explore":["Que leitura provisória organiza melhor o que a pessoa traz","O que ainda falta compreender para sustentar ou rever a hipótese"]}$psych$::jsonb,0,0,array[$psych$Manual Neuropsicologia (CFP)$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
insert into public.psych_curation_items (discipline,kind,label,meta,total_candidates,unique_evidence,sources,evidence,status,copyright,batch) values ('psicologia','axis',$psych$Critérios e diagnóstico diferencial$psych$,$psych${"framework":"Referência (DSM/CID)","summary":"Uso de critérios classificatórios como APOIO à escuta e à diferenciação — nunca como fechamento automático.","draft":"Usar critérios de referência (DSM/CID) como apoio para diferenciar hipóteses, sem qualquer conclusão diagnóstica automática do sistema.","explore":["Quais quadros merecem ser diferenciados diante do que a pessoa relata","Que informações ajudariam a distinguir entre eles"]}$psych$::jsonb,0,0,array[$psych$DSM-5-TR$psych$,$psych$CID-11$psych$]::text[],'[]'::jsonb,'review','draft-synthesis',$psych$2026-07-13T02:18:20.943Z$psych$);
